                                                                                                                                                                                  body: Padding(
                                                                                                                                                                                          padding: const EdgeInsets.all(24.0),
                                                                                                                                                                                                  child: Column(
                                                                                                                                                                                                            mainAxisAlignment: MainAxisAlignment.center,
                                                                                                                                                                                                                      children: [
                                                                                                                                                                                                                                  const Text("به اپلیکیشن کودک ایران خوش آمدید", textAlign: TextAlign.center, style: TextStyle(fontSize: 24)),
